choose.when:
SELECT info.id_ AS orderId, info.type_ AS areaType, info.name_ AS areaName, info.area_id, info.GRP_CODE AS grpCode, info.cust_name AS custName, info.SVC_NUM AS svcNum, info.scheme_name AS schemeName, info.eff_time AS effTime, info.exp_time AS expTime, info.rate AS rate, info.amount_per_year AS amountPerYear, info.scheme_name2 AS schemeName2, info.new_create_time AS newCreateTime, info.eff_time2, info.exp_time2, info.period, info.amount_per_year2 AS amountPerYear2, info.user_addr AS userAddr, info.order_type AS orderType, info.order_number AS orderNumber, (SELECT sc.name_ FROM sys_code sc WHERE sc.type_ = 'order_status' AND sc.code_ = info.status_) AS statusName, info.parent_ AS parentId, info.parentAreaName, info.NEW_SCHEME_ID AS newSchemeId, info.RELATION_TYPE_NAME AS relationTypeName, info.exte_flag AS exteFlag, info.order_flow_no AS orderFlowNo, info.wide_result AS wideResult, info.phase_name AS phaseName, info.actors_info AS actorsInfo, info.create_time AS createTime, info.update_time AS updateTime, info.assignee, info.result, w.user_status AS userStatus , info.business_name AS businessName FROM ( SELECT tt.id_, area.type_ AS type_, area.name_ AS name_, tt.area_id, tt.GRP_CODE, tt.cust_name, tt.SVC_NUM, tt.scheme_name, tt.eff_time, tt.exp_time, tt.rate_ AS rate, tt.amount_per_year, tt.NEW_SCHEME_NAME AS scheme_name2, tt.NEW_CREATE_TIME AS new_create_time, tt.NEW_EFF_TIME AS eff_time2, tt.NEW_EXP_TIME AS exp_time2, tt.NEW_SCHEME_PERIOD AS period, tt.NEW_SCHEME_FEE AS amount_per_year2, tt.user_addr, tt.order_type, tt.order_number, tt.status_, area.parent_ AS parent_, parentArea.name_ AS parentAreaName, tt.NEW_SCHEME_ID, tt.RELATION_TYPE_NAME, tt.exte_flag, tt.order_flow_no, tt.wide_result, tt.phase_name, tt.actors_info, tt.create_time, tt.update_time, (SELECT su1.name_ch FROM act_hi_taskinst his LEFT JOIN sys_user su1 ON su1.id_ = TRIM(BOTH ',' FROM his.ASSIGNEE_) WHERE his.PROC_INST_ID_ = tt.pi_id ORDER BY his.START_TIME_ DESC LIMIT 1) AS assignee, (SELECT REPLACE(ahv.text_, 'null', '') FROM act_hi_taskinst his LEFT JOIN act_hi_varinst ahv ON ahv.task_id_ = his.id_ WHERE his.PROC_INST_ID_ = tt.pi_id AND ahv.name_ = CONCAT(his.TASK_DEF_KEY_, '_resultMemo') ORDER BY his.START_TIME_ DESC LIMIT 1) AS result , sc.name_ AS business_name FROM (
UNION ALL
) tt LEFT JOIN sys_area area ON tt.area_id = area.id_ LEFT JOIN sys_area parentArea ON area.parent_ = parentArea.id_
LEFT JOIN sys_code sc ON sc.code_ = tt.business_dep
WHERE 1=1 AND sc.type_ = 'expandDep' ORDER BY tt.id_ DESC
LIMIT #{startRow}, #{pageSize}
) info LEFT JOIN ftp_tc_user_cycle_warning w ON info.order_flow_no = w.order_flow_no

SELECT tt.id_ AS orderId, area.type_ AS areaType, area.name_ AS areaName, tt.area_id, tt.GRP_CODE AS grpCode, tt.cust_name AS custName, tt.cloud_tag AS cloudTag, tt.consume_type AS consumeType, DATE_FORMAT(tt.consume_time,'%Y-%m-%d %H:%i:%s') AS consumeTime, DATE_FORMAT(tt.end_time,'%Y-%m-%d %H:%i:%s') AS endTime, tt.server_duration AS serverDuration, tt.amount_per_year AS amountPerYear, CASE WHEN tt.new_consume_time IS NULL THEN '否' ELSE '是' END AS exeFlag, tt.new_cloud_tag AS newCloudTag, tt.new_consume_type AS newConsumeType, DATE_FORMAT(tt.new_consume_time,'%Y-%m-%d %H:%i:%s') AS newConsumeTime, DATE_FORMAT(tt.new_end_time,'%Y-%m-%d %H:%i:%s') AS newEndTime, tt.new_server_duration AS newServerDuration, tt.new_amount_per_year AS newAmountPerYear, (SELECT sc.name_ FROM sys_code sc WHERE sc.type_ = 'order_status' AND sc.code_ = tt.status_) AS statusName, tt.order_number AS orderNumber, parentArea.name_ AS parentAreaName, area.parent_ AS parentId, tt.phase_name AS phaseName, tt.actors_info AS actorsInfo, DATE_FORMAT(tt.create_time,'%Y-%m-%d %H:%i:%s') AS createTime, DATE_FORMAT(tt.update_time,'%Y-%m-%d %H:%i:%s') AS updateTime, (SELECT su1.name_ch FROM act_hi_taskinst his LEFT JOIN sys_user su1 ON su1.id_ = TRIM(BOTH ',' FROM his.ASSIGNEE_) WHERE his.PROC_INST_ID_ = tt.pi_id ORDER BY his.START_TIME_ DESC LIMIT 1) AS assignee, (SELECT REPLACE(ahv.text_, 'null', '') FROM act_hi_taskinst his LEFT JOIN act_hi_varinst ahv ON ahv.task_id_ = his.id_ WHERE his.PROC_INST_ID_ = tt.pi_id AND ahv.name_ = CONCAT(his.TASK_DEF_KEY_, '_resultMemo') ORDER BY his.START_TIME_ DESC LIMIT 1) AS result FROM (
UNION ALL
) tt LEFT JOIN sys_area area ON tt.area_id = area.id_ LEFT JOIN sys_area parentArea ON area.parent_ = parentArea.id_ ORDER BY tt.create_time DESC
LIMIT #{startRow}, #{pageSize}

SELECT COUNT(1) FROM ( SELECT tt.id_ FROM (
UNION ALL
) tt LEFT JOIN sys_code sc ON sc.code_ = tt.business_dep WHERE 1=1 AND sc.type_ = 'expandDep' ) tt2

SELECT COUNT(1) FROM (

    UNION ALL

) tt
